import { CookieBanner } from './CookieBanner';
import { SiteConfig } from './SiteConfig';
import { StepLog } from './StepLog';

/**
 * A page that knows when it has loaded. get() checks, as Cypress commands, that it has: each check
 * retries, and fails with a sentence saying what was not ready (the URL, the page load, the title,
 * or the page's key elements). Page objects are made fresh after each navigation:
 * new SomePage().get(). Their methods queue Cypress commands and return the next page object, so a
 * test reads as one chain, as in the Java suites.
 */
export abstract class LoadablePage<T extends LoadablePage<T>> {
  /** The page class's name, for failure messages: HomePage. */
  protected readonly name: string;

  protected constructor(name: string) {
    this.name = name;
  }

  /** Brings the page up if needed. open() navigates, and clicks arrive here, so most pages need nothing. */
  protected load(): void {
    // nothing by default
  }

  /** Checks (as Cypress commands) that the page has fully loaded. */
  protected abstract isLoaded(): void;

  /** Waits until this page has fully loaded; fails saying what was not ready. */
  get(): T {
    this.load();
    this.isLoaded();
    this.recordTiming();
    StepLog.note(`now on ${this.describe()}`);
    return this as unknown as T;
  }

  /** Goes to a path of the site and gets the cookie banner out of the way; isLoaded() does the waiting. */
  protected navigate(path: string): void {
    StepLog.step(`Open ${this.describe()} (${path})`);
    const known = this.knownStatus();
    if (!known) cy.visit(SiteConfig.url(path));
    else {
      // A page known to answer an error (SITE-01): opened whatever it answers, then held to that answer.
      cy.visit(SiteConfig.url(path), { failOnStatusCode: false });
      cy.window({ log: false }).then((win) => {
        const n = win.performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming | undefined;
        const status = n && new URL(n.name).pathname === win.location.pathname ? n.responseStatus : 0;
        if (status === known) StepLog.note(`${this.describe()} answered HTTP ${status} at ${path}, as in the crawl: a known defect (KNOWN-ISSUES.md, SITE-01)`);
        else if (status > 0 && status < 400) StepLog.note(`${this.describe()} answers HTTP ${status} now, not ${known} as in the crawl: SITE-01 is fixed here. Take it out of KNOWN-ISSUES.md; a rebuild from a new crawl drops the known status.`);
        else if (status >= 400) throw new Error(`${this.describe()} answered HTTP ${status} at ${path}: the site did not serve the page, not a page that loaded`);
      });
    }
    CookieBanner.accept();
  }

  /** The status this page type is known to answer, a defect the crawl found (KNOWN-ISSUES.md, SITE-01); 0 for none. Page classes say theirs. */
  protected knownStatus(): number {
    return 0;
  }

  /** What the crawl timed of this page type's pages after their load event, in ms; -1 when it did not. Page classes say theirs. */
  protected crawlSettledMs(): number {
    return -1;
  }

  /**
   * Its row in the run's page timings (cypress.config.ts): when it was ready (now), its first byte,
   * DOM loaded and load event, in ms from the start of its navigation. --expose loadBudget=2.5
   * (seconds) fails a page that takes longer to be ready.
   */
  private recordTiming(): void {
    cy.window({ log: false }).then((win) => {
      const n = win.performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming | undefined;
      const times = n ? [win.performance.now(), n.responseStart, n.domContentLoadedEventEnd, n.loadEventEnd, win.performance.timeOrigin].map(Math.round).join(',') : '';
      const row = { test: Cypress.currentTest.titlePath.join(' > '), page: this.name, path: win.location.pathname, times, crawlSettledMs: this.crawlSettledMs(), budget: String(Cypress.expose('loadBudget') ?? ''), limit: Cypress.config('pageLoadTimeout') };
      cy.task('pageTiming', row, { log: false }).then((over) => {
        if (over) throw new Error(String(over));
      });
    });
  }

  /** This page type in plain English, for steps: ServicesDetailPage -> "the services detail page". */
  describe(): string {
    let out = 'the ';
    for (const [i, c] of [...this.name].entries()) out += i > 0 && c >= 'A' && c <= 'Z' ? ` ${c.toLowerCase()}` : c.toLowerCase();
    return out;
  }

  // ==== YOURS (extras): safe to edit; regenerating keeps what is between these lines ====
  // What every page of this site shares (a common dialog to close, say) goes here.
  // ==== END YOURS (extras) ====
}
